            "onboarding.post.optional": "○ Post Events (optional — AX-only without it)",
            "onboarding.post.stillMissing":
                "Still missing Post Events — DevType will run in AX-only mode. There is no Settings list for this one; try Request again after a Relaunch.",
            "onboarding.im.blocked":
                "Input Monitoring could not be granted. You can continue — Accessibility still enables expansion, but the menu will not show Active until Listen works.",
            "onboarding.verify.title": "Verify",
            "onboarding.verify.body.blocked":
