            "permission.description.microphone":
                "スマート音声入力の録音に必要です。Apple Speech、ローカル AI、ローカル Whisper は端末内で処理し、Gemini は明示的な同意後に録音音声を Google へ送信します。",
            "permission.description.speechRecognition":
